$ErrorActionPreference='Stop';$root='release/compliance-platform/v1.6.0-rc1';$files=@('release-notes.md','changelog.md','validation-report.json','validation-report.md','manifest.sha256','delivery-tags.txt');$dirs=@('runbooks','evidence','configuration','rollback','artifacts');foreach($item in $files){if(!(Test-Path (Join-Path $root $item))){throw "Missing RC file: $item"};Write-Host "$item PASS"};foreach($item in $dirs){if(!(Test-Path (Join-Path $root $item))){throw "Missing RC directory: $item"};Write-Host "$item PASS"};$report=Get-Content "$root/validation-report.json" -Raw|ConvertFrom-Json;if($report.failed-ne 0-or$report.skipped-ne 0-or$report.decision-ne'READY FOR COMPLIANCE RC'){throw 'RC validation report is not ready.'};Write-Host 'Compliance RC package VERIFIED'